        { id = "egg", at = 15, title = "The first meal",
            text = "I hatched in a small hollow in the soil, one of eighty, with a shell as clear and thin as a drop of water. My first meal was my own eggshell. I have thought ever since that a sensible creature begins by taking in where they came from." },
        { id = "middle", at = 40, title = "The middle of the spiral",
            text = "That first clear shell is still with me. I never shed anything. I only added, turn after turn, so the house I was born in sits at the centre of the house I live in now. Look closely and you will find the place: one small pale dot." },
        { id = "path", at = 80, title = "The first crossing",
            text = "The first path I crossed took a whole night: gravel, a boot print, a desert of flagstone. At dawn I looked back and saw a silver line the whole way over. I understood that I had written something, and that every word was true." },
        { id = "dry", at = 140, title = "The dry summer",
            text = "One summer the rain stopped. I glued myself to the wall, sealed my door with a skin as thin as paper, and waited for weeks, hearing the garden crackle. Nobody can make rain come. I learned to wait as if waiting were a place." },
        { id = "crack", at = 220, title = "The crack",
            text = "I fell from that wall once, on to stone. There was a sound I will not describe, and a crack along the last turn of my shell. I mended the crack myself, slowly, from the inside. The line still shows. I have stopped minding." },
        { id = "carried", at = 320, title = "Carried off",
            text = "One evening a hand lifted me out of the lettuces, quite gently, and carried me further than I had ever travelled, over two walls and a lane. I was set down in long grass under a strange sky. I have never gone anywhere so fast, and I did not care for speed." },
        { id = "back", at = 450, title = "The way back",
            text = "Nobody had told me that snails can find the way home. I only knew that one direction felt warmer than the rest. I followed the feeling for nineteen nights. On the twentieth I came over a wall and knew every stone." },
        { id = "question", at = 600, title = "The question",
            text = "And yet, standing on that wall, I was puzzled. I carry my home on my back. I had been at home for all nineteen nights. So what had I been walking toward? I turned the question over for a whole season and got nowhere, comfortably." },
        { id = "trail", at = 800, title = "The other trail",
            text = "That autumn I found a trail I had not made, older than mine, running beside my own for the length of the border. I followed, hoping to meet whoever had gone so steadily. The trail stopped at the foot of an empty chair. I never learned whose." },
        { id = "reader", at = 1050, title = "The slow one",
            text = "Then you came out and sat in that chair with a book, and did not move for an hour, except one hand, now and then, turning a leaf. I had believed I was the slowest creature in the garden. I watched you and thought: here is another, and look how far they go." },
        { id = "answer", at = 1400, title = "An answer, arriving",
            text = "The answer to my old question has nearly reached me. A shell is where I live. Home is what I walked nineteen nights toward. We have read {total} pages now, you turning, I listening from the arm of the chair, and I have not once wished to be further along." },
        { id = "silver", at = 1800, title = "The silver line",
            text = "Look at the garden early, before the dew goes, and you will see everything I ever wrote: thin bright lines, crossing and recrossing, and every one comes at last to where you sit. That is my whole book. I am glad you were the one to read the last page slowly." },
    },
}
